 create(){this.d=loadAuthored(this.cache.json.get('map'));this.makeMap();this.fx=this.add.graphics().setDepth(10000);this.light=this.add.graphics().setDepth(9000).setBlendMode(Phaser.BlendModes.ADD);this.setupInput();this.reset();this.showTitle();this.scale.on('resize',()=>this.resize());document.addEventListener('visibilitychange',()=>{if(document.hidden&&this.active&&!this.paused)this.pause();});window.addEventListener('blur',()=>{this.keysDown.clear();if(this.active&&!this.paused)this.pause();});this.resize();document.querySelector<HTMLCanvasElement>('#game canvas')!.style.filter=`brightness(${settings.brightness})`;}
