  for(let y=0;y<this.d.height;y++)for(let x=0;x<this.d.width;x++){const i=y*this.d.width+x,px=x*32,py=y*32,isWall=wall(x,y),n=((x*73856093)^(y*19349663))>>>0;
   if(bridgeTile(x,y)){
    const glow=c.createLinearGradient(px,py,px,py+32);glow.addColorStop(0,'#071d25');glow.addColorStop(.5,'#02080d');glow.addColorStop(1,'#0b2d35');c.fillStyle=glow;c.fillRect(px,py,32,32);
    c.fillStyle='#2f9b9d24';c.fillRect(px,py+6,32,3);c.fillRect(px,py+24,32,2);c.strokeStyle='#69d7c135';c.beginPath();c.moveTo(px+4,py+2);c.lineTo(px+25,py+30);c.moveTo(px+28,py+4);c.lineTo(px+10,py+31);c.stroke();
   }else if(!isWall){
    const floor=c.createLinearGradient(px,py,px,py+32);const shade=['#667672','#707d75','#62736f','#5b6c69'][n%4];floor.addColorStop(0,'#89918a');floor.addColorStop(.2,shade);floor.addColorStop(1,'#3c504f');c.fillStyle=floor;c.fillRect(px,py,32,32);
    c.globalAlpha=.28;const floorTile=[0,1,2,6][n%4];c.drawImage(atlas,(floorTile%8)*128+30,Math.floor(floorTile/8)*128+36,72,68,px,py,32,32);c.globalAlpha=1;
    c.strokeStyle='#d6d1b84a';c.strokeRect(px+.5,py+.5,31,31);c.fillStyle='#06151a65';c.fillRect(px,py+29,32,3);
    if(n%7===0){c.strokeStyle='#112a303d';c.beginPath();c.moveTo(px+4,py+3);c.lineTo(px+13,py+14);c.lineTo(px+8,py+24);c.stroke();}
    if(wall(x,y-1)){c.fillStyle='#071217a8';c.fillRect(px,py,32,11);c.fillStyle='#c3aa70a8';c.fillRect(px,py,32,2);c.fillStyle='#816c43aa';c.fillRect(px,py+3,32,2);}
    if(wall(x-1,y)){c.fillStyle='#06121848';c.fillRect(px,py,6,32);}
   }else{
    const stone=['#1b2b32','#1e3038','#26353b'][n%3];c.fillStyle=stone;c.fillRect(px,py,32,32);c.fillStyle='#0a151b';c.fillRect(px,py+15,32,17);c.strokeStyle='#09161b';c.strokeRect(px+.5,py+.5,31,15);c.strokeRect(px-15.5,py+16.5,31,15);c.strokeStyle='#66727666';c.beginPath();c.moveTo(px+1,py+1);c.lineTo(px+31,py+1);c.stroke();
    if(!wall(x,y+1)){c.fillStyle='#050d12';c.fillRect(px,py+18,32,14);c.fillStyle='#c7ad70';c.fillRect(px,py+3,32,3);c.fillStyle='#715936';c.fillRect(px,py+6,32,4);c.fillStyle='#a1926f';c.fillRect(px,py+10,32,2);}
    if(!wall(x+1,y)){c.fillStyle='#c1ab71';c.fillRect(px+28,py,4,32);}if(!wall(x-1,y)){c.fillStyle='#897344';c.fillRect(px,py,4,32);}if(!wall(x,y-1)){c.fillStyle='#d0b87b';c.fillRect(px,py,32,3);}
   }
  }

  // Inlaid ward medallions give chambers an identity without obscuring the floor.
  for(let z=1;z<=8;z++){const cells=this.d.zones.map((v,i)=>v===z&&!this.d.collision[i]?i:-1).filter(i=>i>=0);if(!cells.length)continue;const cx=cells.reduce((sum,i)=>sum+i%this.d.width,0)/cells.length*32+16,cy=cells.reduce((sum,i)=>sum+Math.floor(i/this.d.width),0)/cells.length*32+16;if(wall(Math.floor(cx/32),Math.floor(cy/32)))continue;c.save();c.beginPath();for(const i of cells)c.rect(i%this.d.width*32,Math.floor(i/this.d.width)*32,32,32);c.clip();c.translate(cx,cy);c.strokeStyle=z===8?'#b191585e':'#d5c18b38';c.lineWidth=2;const r=z===1?67:z===8?105:83;for(const radius of [r,r-7,r*.47]){c.beginPath();c.arc(0,0,radius,0,Math.PI*2);c.stroke();}for(let k=0;k<12;k++){c.save();c.rotate(k*Math.PI/6);c.fillStyle='#d8c59366';c.fillRect(-1,-r+12,2,7);c.restore();}c.beginPath();c.moveTo(0,-r*.4);c.lineTo(r*.28,0);c.lineTo(0,r*.4);c.lineTo(-r*.28,0);c.closePath();c.stroke();c.restore();}
  tex.refresh();this.world=this.add.image(0,0,'floor').setOrigin(0).setDepth(-100);this.cameras.main.setBackgroundColor('#050d12');
